RamProfile actualRamProfile(const V&effective,const std::set<std::string>&casualties){const auto&crew=effective.get("crew");const auto&members=crew.get("members").resolved();if(members.kind!=V::Kind::Array)throw std::invalid_argument("Native player RAM crew snapshot is unavailable");std::set<std::string>roster;for(const auto&m:members.array)roster.insert(m.get("instance").resolved().text);for(const auto&n:casualties)if(!roster.count(n))throw std::invalid_argument("Native player RAM casualty is outside crew snapshot");double level=0.;for(const auto&m:members.array)if(!casualties.count(m.get("instance").resolved().text))for(const auto&skill:m.get("skills").resolved().array)if(skill.get("name").resolved().text=="driver_rammingmaster"&&skill.get("active").resolved().kind==V::Kind::Boolean&&skill.get("active").truth()&&skill.get("enabled").resolved().kind==V::Kind::Boolean&&skill.get("enabled").truth())level=std::max(level,skill.get("level").numeric());const auto&spall=effective.get("ramming").get("spall_coefficient").resolved();if(spall.kind!=V::Kind::Number&&spall.kind!=V::Kind::Integer)throw std::invalid_argument("Native player RAM spall coefficient is unavailable");RamProfile out{spall.numeric(),level*.0015};if(!std::isfinite(out.spall_coefficient)||out.spall_coefficient<1.||!std::isfinite(out.ramming_bonus)||out.ramming_bonus<0.||out.ramming_bonus>.15)throw std::invalid_argument("Native player RAM profile is invalid");return out;}
