  const double dx=own.x-other.x,dy=own.y+(own.shape[2]+own.shape[3])*.5-other.y-(other.shape[2]+other.shape[3])*.5,dz=own.z-other.z,distance=dx*dx+dy*dy+dz*dz;if(distance<=0.){if(previous.count(id))closing.insert(id);continue;}const double relative=((own.vx-other.vx)*dx+(own.vy-other.vy)*dy+(own.vz-other.vz)*dz)/std::sqrt(distance);if(!overlap(own,other)){if(previous.count(id)&&relative<0.)closing.insert(id);continue;}overlapping.insert(id);const auto impact_=impact(own,other);const auto normal_=impact_?normal(*impact_):std::optional<Vec>{};if(!normal_)continue;const auto poly=polygon(own,other);if(poly.empty())continue;Vec center{};for(const auto&v:poly){center[0]+=v[0];center[1]+=v[1];}for(auto&v:center)v/=double(poly.size());if(relative>=0.||previous.count(id)||!motion||!peer.actor)continue;
  const double low=std::max(own.y+own.shape[2],other.y+other.shape[2]),high=std::min(own.y+own.shape[3],other.y+other.shape[3]);const auto a=vertical(own),b=vertical(other);const Vec span{std::max(a[0],b[0]),std::min(a[1],b[1])};const Point hit{double(float(center[0])),double(float((low+high)*.5)),double(float(center[1]))};auto ownpose=pose(own);ownpose[4]=local_pitch;ownpose[5]=local_roll;const bool queued=o.queue(peer,hit,{own.vx,own.vy,own.vz},{other.vx,other.vy,other.vz},*motion,ownpose,pose(other),own.shape,normal_,span,profile);if(queued||o.pending(id))newly.insert(id);
